/* ------------------------------------------------------------------ */
/*  ICD-10 DISEASE LIBRARY                                             */
/*  Comprehensive catalog of diseases with ICD-10 codes.              */
/*  Tracked diseases are flagged and link to MV-AIHS surveillance data */
/* ------------------------------------------------------------------ */

export interface IcdDisease {
  /** Unique slug used in filter state (e.g. "dengue", "a09", "j11") */
  code: string;
  name: string;
  icd10: string;
  /** Broad clinical/administrative chapter */
  chapter: string;
  /** Fine category for search/grouping */
  category: string;
  /** True = MV-AIHS has encounter data for this disease */
  tracked: boolean;
  notifiable?: boolean;
}

/** Diseases that have real encounter data in MV-AIHS surveillance */
export const TRACKED_CODES = new Set<string>([
  "ili","dengue","gastro","febrile_seizure","chest_pain",
  "dehydration","influenza","pneumonia","diarrhea","hfmd",
]);

