export const ICD_DISEASE_LIBRARY: IcdDisease[] = ICD_DISEASES;

/** Subset exported for backward compat with surveillance analytics */
export const TRACKED_ICD_DISEASES = ICD_DISEASES.filter((d) => d.tracked);

export function searchIcdLibrary(query: string): IcdDisease[] {
  const q = query.trim().toLowerCase();
  if (!q) return ICD_DISEASE_LIBRARY;
  return ICD_DISEASE_LIBRARY.filter((d) =>
    d.name.toLowerCase().includes(q) ||
    d.icd10.toLowerCase().includes(q) ||
    d.code.toLowerCase().includes(q) ||
    d.category.toLowerCase().includes(q) ||
    d.chapter.toLowerCase().includes(q)
  );
}
